<?php
require_once __DIR__.'/../includes/bootstrap.php';$actor=club_require_capability('users.manage');$error='';
$allowedRoles=['member','publisher','treasurer','administrator'];$categories=['general','membership','hall_hire'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();$id=(int)($_POST['user_id']??0);$status=(string)($_POST['status']??'');$roles=array_values(array_intersect($allowedRoles,(array)($_POST['roles']??[])));$routes=array_values(array_intersect($categories,(array)($_POST['routes']??[])));
 if(!in_array($status,['pending','active','suspended'],true))$error='Choose a valid account status.';
 elseif($id===(int)$actor['id'])$error='Ask another administrator to change your own permissions or account status.';
 else {db()->beginTransaction();try{
 $s=db()->prepare('SELECT * FROM club_users WHERE id=? FOR UPDATE');$s->execute([$id]);$target=$s->fetch();if(!$target)throw new RuntimeException('Account not found.');
 if(club_user_has_role($id,'administrator') && ($status!=='active' || !in_array('administrator',$roles,true))){$s=db()->query("SELECT u.id FROM club_users u JOIN club_user_roles r ON r.user_id=u.id WHERE r.role='administrator' AND u.status='active' AND u.email_verified_at IS NOT NULL FOR UPDATE");if(count($s->fetchAll())<=1)throw new RuntimeException('Keep at least one active, verified club administrator.');}
 db()->prepare('UPDATE club_users SET status=? WHERE id=?')->execute([$status,$id]);
 if(!empty($_POST['verify_email']))db()->prepare('UPDATE club_users SET email_verified_at=COALESCE(email_verified_at,NOW()) WHERE id=?')->execute([$id]);
 db()->prepare('DELETE FROM club_user_roles WHERE user_id=?')->execute([$id]);foreach($roles as $role)db()->prepare('INSERT INTO club_user_roles(user_id,role) VALUES(?,?)')->execute([$id,$role]);
 db()->prepare('DELETE FROM club_enquiry_routes WHERE user_id=?')->execute([$id]);foreach($routes as $route)db()->prepare('INSERT INTO club_enquiry_routes(user_id,category) VALUES(?,?)')->execute([$id,$route]);
 db()->prepare("INSERT INTO club_outbox(channel,event_key,payload,status) VALUES('audit',?,?,'sent')")->execute(['roles-'.bin2hex(random_bytes(12)),json_encode(['action'=>'user.permissions','actor_user_id'=>$actor['id'],'legacy_admin_id'=>$actor['legacy_admin']??false?($_SESSION['admin_id']??null):null,'target_user_id'=>$id,'status'=>$status,'roles'=>$roles,'enquiry_routes'=>$routes,'email_verified_by_admin'=>!empty($_POST['verify_email'])],JSON_THROW_ON_ERROR)]);
 db()->commit();flash_success('Account permissions saved.');redirect('/admin/club-users.php?user='.$id);
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'The account could not be updated. Please try again.';}}
}
$q=trim((string)($_GET['q']??''));$s=db()->prepare('SELECT id,full_name,email,status,email_verified_at FROM club_users WHERE full_name LIKE ? OR email LIKE ? ORDER BY full_name LIMIT 100');$s->execute(['%'.$q.'%','%'.$q.'%']);$users=$s->fetchAll();
$selected=null;$roles=[];$routes=[];if(!empty($_GET['user'])){$s=db()->prepare('SELECT id,full_name,email,status,email_verified_at FROM club_users WHERE id=?');$s->execute([(int)$_GET['user']]);$selected=$s->fetch();if($selected){$s=db()->prepare('SELECT role FROM club_user_roles WHERE user_id=?');$s->execute([$selected['id']]);$roles=$s->fetchAll(PDO::FETCH_COLUMN);$s=db()->prepare('SELECT category FROM club_enquiry_routes WHERE user_id=?');$s->execute([$selected['id']]);$routes=$s->fetchAll(PDO::FETCH_COLUMN);}}
club_member_layout_start('People & roles');?>
<p>Give each person only the access they need. Membership payments never grant committee permissions.</p>
<?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?>
<?php if($selected):?><form method="post" class="platform-panel"><?php csrf_field();?><input type="hidden" name="user_id" value="<?=(int)$selected['id']?>"><h2><?=e($selected['full_name'])?></h2><p><?=e($selected['email'])?></p><div class="form-field"><label for="status">Account status</label><select id="status" name="status"><?php foreach(['pending','active','suspended'] as $status):?><option value="<?=e($status)?>"<?=$selected['status']===$status?' selected':''?>><?=e(ucfirst($status))?></option><?php endforeach;?></select></div>
<fieldset><legend>Website roles</legend><?php foreach($allowedRoles as $role):?><p><label><input type="checkbox" name="roles[]" value="<?=e($role)?>"<?=in_array($role,$roles,true)?' checked':''?>> <?=e(ucfirst($role))?></label></p><?php endforeach;?></fieldset><p>Treasurer is required for financial reconciliation, including for administrators.</p>
<fieldset><legend>Assigned enquiry categories</legend><?php foreach($categories as $category):?><p><label><input type="checkbox" name="routes[]" value="<?=e($category)?>"<?=in_array($category,$routes,true)?' checked':''?>> <?=e(ucwords(str_replace('_',' ',$category)))?></label></p><?php endforeach;?></fieldset>
<?php if(!$selected['email_verified_at']):?><p><label><input type="checkbox" name="verify_email" value="1"> I have checked this person’s email address and confirm it is theirs.</label></p><?php else:?><p>Email verified.</p><?php endif;?><button class="btn btn--primary">Save permissions</button></form><?php endif;?>
<section class="platform-panel"><form method="get"><div class="form-field"><label for="q">Find a member</label><input id="q" name="q" maxlength="190" value="<?=e($q)?>"></div><button class="btn btn--secondary">Search</button></form><p>Showing up to 100 accounts. Search by name or email to narrow the list.</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Verification</th><th>Manage</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['email'])?></td><td><?=e(ucfirst($u['status']))?></td><td><?=$u['email_verified_at']?'Verified':'Awaiting verification'?></td><td><a href="<?=e(site_url('/admin/club-users.php?user='.$u['id']))?>">Permissions</a></td></tr><?php endforeach;?></tbody></table></div></section>
<?php club_member_layout_end();?>
